<!-- Modified 2026-10-29 for the independent Simulation Lab edition; see NOTICE and MODIFICATIONS.md. -->
<template>
  <section class="knowledge-panel">
    <div class="heading"><div><p class="eyebrow">PRODUCT KNOWLEDGE / SUPPLIED SOURCES</p><h2>Start with what the sources say.</h2></div><span>Local search · No model calls</span></div>
    <p class="scope">{{ overview?.scope || 'Loading the source catalog…' }} Previous synthetic fixtures and reports are engine demonstrations, not SimLab product evidence.</p>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <p v-if="message" class="message" role="status">{{ message }}</p>
    <div class="metrics" v-if="overview"><div><strong>{{ overview.selected_artifacts }}</strong><span>Selected design artifacts</span></div><div><strong>{{ overview.local_documents }}</strong><span>Local documents</span></div><div><strong>{{ overview.production_pages }}</strong><span>Public pages captured</span></div><div><strong>{{ overview.assertions }}</strong><span>Source assertions</span></div><div><strong>{{ overview.conflicts }}</strong><span>Unresolved conflicts</span></div></div>
    <details class="provenance" v-if="overview"><summary>Collection scope and provenance</summary><p>{{ overview.source_root }}</p><p>Source Git HEAD: {{ overview.git_head }}</p><p>Local snapshot: {{ overview.collected_at }} · Public snapshot: {{ overview.production_collected_at }}</p><p>Production was read through public GET navigation only. No login, clicks, submission or transaction. Source working-copy changes were preserved. Formal design approval and actual deployment are separate.</p></details>
    <div class="library"><label>Domain summary<select v-model="selectedDocument" @change="loadDocument"><option v-for="(file,key) in overview?.documents || {}" :key="key" :value="key">{{ names[key] || key }}</option></select></label><a :href="'/api/simlab/knowledge/documents/'+selectedDocument" target="_blank" rel="noopener">Open Markdown ↗</a><button type="button" @click="addMaterial" :disabled="busy">Add domain summary to simulation materials</button></div>
    <details><summary>Read selected summary</summary><pre class="summary-text">{{ summary }}</pre></details>
    <form @submit.prevent="search" class="search-form"><label for="knowledge-query">Search the source evidence<input id="knowledge-query" v-model="query" placeholder="deposit authentication, commission masterpiece, business verification" maxlength="250"></label><button :disabled="busy || !query.trim()">Search sources</button><label class="check"><input type="checkbox" v-model="includeHistory">Include older/unselected history</label></form>
    <p class="hint">Search results can conflict. “Approved design” does not mean verified backend behavior. Historical/draft files are excluded by default where the catalog identifies them.</p>
    <div v-if="searched" class="search-results">
      <h3>Reviewed assertions</h3><p v-if="!assertions.length" class="hint">No matching assertion. Check source matches and the missing-specification register.</p>
      <article v-for="fact in assertions" :key="fact.id"><p class="badge">{{ fact.id }} · {{ fact.evidence_class }}</p><p>{{ fact.claim }}</p><div v-for="(citation,i) in fact.evidence" :key="i" class="citation"><button type="button" class="source-link" @click="readSource(citation.source_id)">{{ citation.path || citation.url }}</button><small>{{ citation.locator_kind }} {{ citation.line_start }}<template v-if="citation.line_end!==citation.line_start">–{{ citation.line_end }}</template> · {{ citation.approval_status || 'public observation' }}</small></div></article>
      <h3>Source matches</h3><p v-if="!matches.length" class="hint">No source match for this query.</p><article v-for="(match,i) in matches" :key="match.id+'-'+i"><p class="badge">{{ match.category }} · approval: {{ match.approval }}</p><button type="button" class="source-link" @click="readSource(match.id)">{{ match.title || match.source }}</button><p class="source-path">{{ match.source }}</p><p class="excerpt">{{ match.excerpt }}</p></article>
    </div>
    <details open v-if="source"><summary>Captured source — {{ source.title }}</summary><p class="source-path">{{ source.path || source.url }}</p><p class="hint">{{ source.category }} · approval: {{ source.approval_status }} · {{ source.source_kind }}<br>SHA256: {{ source.sha256 }}<br>{{ source.content_completeness || 'Static design extraction includes documentation and hidden prototype panels.' }}</p><pre>{{ source.text }}</pre><details><summary>Control inventory and source lines</summary><pre>{{ JSON.stringify(source.controls,null,2) }}</pre></details></details>
    <details class="conflicts" @toggle="loadConflicts"><summary>Policy conflicts and missing specifications ({{ overview?.conflicts || 0 }})</summary><article v-for="c in conflicts" :key="c.id"><h3>{{ c.id }} · {{ c.title }}</h3><p>{{ c.handling }}</p><ul><li v-for="(s,i) in c.sources" :key="i"><code>{{ s.path_or_url }}</code> — {{ s.locator }}</li></ul></article></details>
  </section>
</template>

<script setup>
import { ref,onMounted } from 'vue'
const emit=defineEmits(['material-added'])
const overview=ref(null),query=ref(''),includeHistory=ref(false),matches=ref([]),assertions=ref([]),source=ref(null),conflicts=ref([])
const selectedDocument=ref('overview'),summary=ref(''),error=ref(''),message=ref(''),busy=ref(false),searched=ref(false)
const names={overview:'Knowledge overview and scope',rules:'Product and transaction rules',buyer:'Buyer journey and payments',seller:'Seller, Seller Offer and pre-authentication',merchant:'B2C merchant gaps',conflicts:'Conflicts and unresolved decisions',catalog:'Source catalog and coverage'}
async function api(path,options={}){const r=await fetch('/api/simlab/knowledge'+path,{...options,headers:{'Content-Type':'application/json'}});const value=await r.json();if(!r.ok||value.success===false)throw new Error(value.error||'Knowledge request failed');return value}
async function action(fn){error.value='';message.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadDocument(){await action(async()=>{const r=await fetch('/api/simlab/knowledge/documents/'+selectedDocument.value);if(!r.ok)throw new Error('Knowledge document not available.');summary.value=await r.text()})}
async function search(){await action(async()=>{const r=await api('/search?q='+encodeURIComponent(query.value)+'&history='+includeHistory.value);matches.value=r.data;assertions.value=r.facts;searched.value=true})}
async function readSource(id){await action(async()=>{source.value=(await api('/sources/'+encodeURIComponent(id))).data})}
async function loadConflicts(event){if(!event.target.open||conflicts.value.length)return;await action(async()=>{conflicts.value=(await api('/conflicts')).data})}
async function addMaterial(){await action(async()=>{const r=await api('/materials/'+selectedDocument.value,{method:'POST',body:'{}'});emit('material-added',r.data);message.value='Source-labeled material added. Review it alongside the scenario policies and unresolved conflicts before running.'})}
onMounted(async()=>{await action(async()=>{overview.value=(await api('')).data});await loadDocument()})
</script>

<style scoped>
.knowledge-panel{border:1px solid #cbd8c2;background:#fff;padding:28px;margin:28px 0;color:#293a23;font:13px/1.65 Arial,sans-serif}.heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.eyebrow{font-size:10px;letter-spacing:1.7px;color:#75876b;margin-bottom:8px}.heading h2{font-size:25px;font-weight:500;letter-spacing:-.5px}.heading>span{font-size:10px;color:#7e8c74}.scope{padding:14px;background:#f0f3e9;border-left:3px solid #8c9d79;font-size:11px;margin:20px 0}.metrics{display:flex;flex-wrap:wrap;gap:18px 35px;margin:18px 0}.metrics div{display:flex;flex-direction:column}.metrics strong{font-size:24px;font-weight:500}.metrics span,.hint{font-size:10px;color:#7d8b72}.hint{margin:12px 0;line-height:1.7}.library,.search-form{display:flex;align-items:end;gap:16px;flex-wrap:wrap;border-top:1px solid #e3eadd;padding-top:18px;margin-top:18px}label{font-size:11px;color:#526947;display:block}input:not([type=checkbox]),select{display:block;border:1px solid #d5dfcb;padding:11px;margin-top:6px;background:#fcfdf9;color:#293d22;max-width:100%;font:12px Arial,sans-serif}.search-form label:first-child{flex:1;min-width:200px}.search-form input:not([type=checkbox]){width:100%}.check{display:flex;align-items:center;gap:7px;padding-bottom:10px}.library button,.search-form button{border:1px solid #c9d6bd;background:#edf3e6;padding:11px 13px;color:#345029;cursor:pointer;font-size:11px}button:disabled{opacity:.45;cursor:default}a,.source-link{color:#4e7140;font-size:11px}.library a{padding-bottom:9px}details{margin:15px 0}summary{cursor:pointer;color:#617a50;font-size:11px}.provenance p{font-size:10px;overflow-wrap:anywhere;margin:8px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7ee;padding:15px;max-height:400px;overflow:auto;font-size:10px;line-height:1.7;margin:10px 0}.summary-text{max-height:350px}article{border-top:1px solid #e4ebdc;padding:15px 0}.badge{font-size:9px;text-transform:uppercase;letter-spacing:.6px;color:#80916e;margin-bottom:7px}article>p{font-size:12px;line-height:1.7}h3{font-size:13px;font-weight:600;margin:20px 0 10px}.source-link{border:0;padding:0;background:none;text-align:left;cursor:pointer;text-decoration:underline;overflow-wrap:anywhere}.citation{margin-top:10px}.citation small{display:block;font-size:9px;color:#88977b}.source-path{font-size:10px!important;color:#7c8e6b;overflow-wrap:anywhere;margin:6px 0}.excerpt{white-space:pre-wrap}.conflicts ul{padding-left:18px;font-size:10px;overflow-wrap:anywhere}.error{background:#fff0e8;color:#9b4b2c;padding:12px;font-size:11px}.message{background:#edf5e5;color:#4a6b34;padding:12px;font-size:11px}@media(max-width:650px){.knowledge-panel{padding:18px}.heading{align-items:flex-start;flex-direction:column;gap:8px}.metrics{gap:15px 22px}.metrics span{max-width:120px}.library select{width:100%}.library label{width:100%}}
</style>
